import { Component, EventEmitter, Input, OnChanges, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { NotesService, Note } from '../../services/notes.service';

@Component({
  selector: 'app-note-editor',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './note-editor.component.html',
  styleUrls: ['./note-editor.component.scss']
})
export class NoteEditorComponent implements OnChanges {
  @Input() note?: Note;
  @Output() saved = new EventEmitter<Note>();
  @Output() cancel = new EventEmitter<void>();

  title = '';
  content = '';

  constructor(private notesService: NotesService) {}

  ngOnChanges(): void {
    if (this.note) {
      this.title = this.note.title;
      this.content = this.note.content;
    } else {
      this.title = '';
      this.content = '';
    }
  }

  onSubmit() {
    const payload = { title: this.title, content: this.content };
    if (this.note) {
      this.notesService.updateNote(this.note.id, payload).subscribe(n => this.saved.emit(n));
    } else {
      this.notesService.createNote(payload).subscribe(n => this.saved.emit(n));
    }
  }
}
<form (ngSubmit)="onSubmit()" aria-label="Note editor form">
  <div class="field">
    <label for="title">Title</label>
    <input id="title" class="input" [(ngModel)]="title" name="title" required placeholder="Note title" />
  </div>
  <div class="field">
    <label for="content">Content</label>
    <textarea id="content" class="textarea" [(ngModel)]="content" name="content" rows="10" placeholder="Write your note..."></textarea>
  </div>
  <div class="actions">
    <button type="submit" class="btn" aria-label="Save note">Save</button>
    <button type="button" class="btn btn-secondary" (click)="cancel.emit()" aria-label="Cancel editing">Cancel</button>
  </div>
</form>
